// BenchmarkStoreSuite measures each callable of the suite of Store on
// storeIdle.
func BenchmarkStoreSuite(b *testing.B) {
	b.Run("Hasher", func(b *testing.B) {
		castest.BenchStoreSuite(b, castest.StoreChecks.Hasher.Callable, storeIdle)
	})
	b.Run("Put", func(b *testing.B) {
		castest.BenchStoreSuite(b, castest.StoreChecks.Put.Callable, storeIdle)
	})
	b.Run("Get", func(b *testing.B) {
		castest.BenchStoreSuite(b, castest.StoreChecks.Get.Callable, storeIdle)
	})
	b.Run("Has", func(b *testing.B) {
		castest.BenchStoreSuite(b, castest.StoreChecks.Has.Callable, storeIdle)
	})
}

